import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, step, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const root = new Group();

  // 1. STAGE BACKGROUND (Avoid flat void)
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);

  // Vertical gradient Node logic
  const vUv = uv();
  bgMat.colorNode = mix(vec3(inkColor.r, inkColor.g, inkColor.b), vec3(surfaceColor.r, surfaceColor.v, surfaceColor.b), vUv.y);

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // 2. HERO CARD
  // Interactive 3D Card
  const cardGeo = new PlaneGeometry(2.2, 1.4);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 1.0
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  root.add(cardMesh);

  // Load the card texture
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  });

  // Local Lighting: Accent Rim Light for the machined/precision look
  const rimLight = new DirectionalLight(colors.accent, 1.2);
  rimLight.position.set(-2, 3, 2);
  root.add(rimLight);

  // 3. TEXT LAYER (MSDF)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = items.find(i => i.role === 'headline' || i.text.includes('Journal'))?.text ?? 'Journal 2';

  const textNode = ctx.fontAtlas.createText(labelText, {
    fontSize: 0.14,
    color: colors.paper,
    align: 'center'
  });
  // Position text nicely below the center image area
  textNode.position.set(0, -0.9, 0.05);
  root.add(textNode);

  // 4. ANIMATION & INTERACTIVE STATE
  const state = {
    hoverTimeline: null,
    pressTimeline: null
  };

  root.userData.handlers = {
    pointerover: () => {
      if (state.hoverTimeline) state.hoverTimeline.kill();
      state.hoverTimeline = gsap.timeline();
      // Subtle rise-in of 0.15 scene units and accent tilt
      state.hoverTimeline.to(cardMesh.position, {
        z: 0.15,
        y: 0.05,
        duration: 0.4,
        ease: 'power3.out'
      });
      state.hoverTimeline.to(cardMesh.rotation, {
        y: 0.05,
        x: -0.03,
        duration: 0.4,
        ease: 'power3.out'
      }, 0);
    },
    pointerout: () => {
      if (state.hoverTimeline) state.hoverTimeline.kill();
      state.hoverTimeline = gsap.timeline();
      state.hoverTimeline.to(cardMesh.position, {
        z: 0,
        y: 0,
        duration: 0.6,
        ease: 'power4.out'
      });
      state.hoverTimeline.to(cardMesh.rotation, {
        y: 0,
        x: 0,
        duration: 0.6,
        ease: 'power4.out'
      }, 0);
    },
    click: () => {
      // Press-down on click
      if (state.pressTimeline) state.pressTimeline.kill();
      state.pressTimeline = gsap.timeline();
      state.pressTimeline.to(cardMesh.scale, {
        x: 0.96,
        y: 0.96,
        z: 0.96,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
      state.pressTimeline.to(cardMesh.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.3,
        ease: 'power2.out'
      });

      ctx.emit('hub-journal.select', { id: 'journal-2' });
    }
  };

  // 5. CINEMATIC PRIMITIVES
  const primitivesInstances = [];
  const primitives = config.cinematicPrimitives ?? [{ name: 'parallax-scroll', params: { intensity: 0.25 } }];

  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const instance = ctx.primitives[prim.name](cardMesh, prim.params);
      if (instance) primitivesInstances.push(instance);
    }
  }

  // 6. CLEANUP
  root.userData.cleanup = () => {
    if (state.hoverTimeline) state.hoverTimeline.kill();
    if (state.pressTimeline) state.pressTimeline.kill();
    primitivesInstances.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    cardGeo.dispose();
    cardMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
  };

  return root;
}
